import{r as $,ag as K,ah as U,j as R,ai as ne,K as O}from"./index.template-DXMBR0gG.js";import{warmAudio as re,createAdvMusic as ce}from"./adventure-music-qk8oicAo.js";import{f as he}from"./cg-finish-B06rGLye.js";import{g as Q}from"./adv-gfx-DkmTjaf5.js";const f=(t,a,s)=>({ic:t,h:a,b:s}),fe=[{id:"posture",title:"Sit so your hands can relax",sub:"Posture and freedom",hue:190,slides:[f("🪑","Find your height","Sit so your forearms are about level with the keys, with your elbows a little in front of your body."),f("🦶","Feet on the floor","Let both feet rest flat, so your back and shoulders are not holding you up."),f("🫁","Breathe out","Check your shoulders. If they are near your ears, breathe out and let them drop."),f("🎯","Try this today","Before you play, take three slow breaths and shake out your hands for ten seconds.")]},{id:"relax",title:"Why tension slows you down",sub:"Relaxed hands move faster",hue:140,slides:[f("✊","Tight hands tire","A hand that grips the keys uses more energy and gets tired quickly."),f("🪶","Weight, not force","Let the weight of your arm sink into each key, instead of pushing down with muscle."),f("🔍","Look for tight spots","Wrists, thumbs and shoulders often hold tension without you noticing."),f("🎼","Try this today","Play a slow scale and stop at every note. Ask yourself, is anything tight right now?")]},{id:"slow",title:"The power of playing slowly",sub:"Slow is how fast is built",hue:30,slides:[f("🐢","Slow first","When you play slowly, your brain has time to choose each finger and each note on purpose."),f("🧱","Build the path","Careful slow repeats build a clean path, and speed can then grow on top of it."),f("📈","Raise it in small steps","When it is clean three times in a row, raise the speed just a little."),f("✅","Try this today","Pick one hard bar and play it at half speed until it feels easy.")]},{id:"metronome",title:"Making friends with the metronome",sub:"A steady pulse",hue:250,slides:[f("⏱️","A steady friend","A metronome is not a judge. It simply keeps the beat steady so you can notice yours."),f("🐌","Start slow","Set it slow enough that you never rush, even in the hard places."),f("👂","Listen between clicks","Try to land your notes right on the click, so your ear learns what steady sounds like."),f("🔧","Try this today","Practise one passage with the metronome, then play it once without and compare.")]},{id:"reading",title:"Reading music without panic",sub:"Sight-reading skills",hue:60,slides:[f("👀","Look ahead","Good readers keep their eyes one beat ahead of their hands, like reading a book."),f("🔁","Keep going","Do not stop to fix mistakes. Keep the beat moving, because that is what a real reading is."),f("🧩","See patterns","Notice steps, skips, repeated notes and chords, instead of naming every single note."),f("📖","Try this today","Read one easy new piece every day. Easy and new beats hard and familiar for reading.")]},{id:"ear",title:"Training your ear",sub:"Hear it before you play it",hue:300,slides:[f("👂","Ears lead","The ear is a musician's most important tool, and it can be trained like a muscle."),f("🎤","Sing it first","Hum or sing the next phrase before you play it. Your fingers follow what your ear expects."),f("↕️","Up or down","Start with the simple question: did that note go up or down?"),f("🎶","Try this today","Pick a song you know and try to find its first five notes by ear.")]},{id:"scales",title:"Why scales are worth it",sub:"A map of the keyboard",hue:100,slides:[f("🗺️","A map of keys","Most music is built from scales, so practising them is learning the map."),f("✋","Fingering habits","Scales teach your hand the fingering patterns it will meet again and again in pieces."),f("🎚️","Even sound","Try to make every note the same loudness and length. That is a clear, simple goal."),f("⏳","Try this today","Two minutes of one scale, slowly and evenly, before your piece.")]},{id:"hands",title:"Hands separate, then together",sub:"Divide and combine",hue:340,slides:[f("🙌","Divide","A hard passage is easier when you learn each hand alone first."),f("🔬","Know each part","Play the left hand until you do not have to think about it, then the right."),f("🤝","Join slowly","Put the hands together at a slow speed. It is normal for it to feel clumsy at first."),f("🧠","Try this today","Take four bars. Left hand, right hand, then both slowly. Repeat the next day.")]},{id:"mistakes",title:"Mistakes are information",sub:"Learning from errors",hue:0,slides:[f("❌","Not a failure","A wrong note tells you exactly where the practice needs to go."),f("🔎","Find the cause","Was it the fingering, the rhythm, or the reading? Fix the cause, not just the note."),f("♻️","Fix and repeat","After you fix it, play the spot correctly several times so the right way becomes the habit."),f("😊","Try this today","When you miss a note, say out loud what went wrong, then try again calmly.")]},{id:"sleep",title:"Sleep helps you remember",sub:"Practice and rest",hue:230,slides:[f("🌙","The brain keeps working","Research suggests that sleep helps the brain sort and strengthen what you learned that day."),f("📆","Little and often","That is one more reason a short practice every day works better than a long cram."),f("🌅","Morning check","Sometimes a passage feels easier the next day, even though you did nothing else."),f("🛏️","Try this today","Practise your hardest spot in the evening, and test it again tomorrow morning.")]},{id:"breaks",title:"Take breaks and come back",sub:"Spaced practice",hue:120,slides:[f("⏸️","Rest on purpose","Short breaks help you stay sharp, and your attention drops when you push without stopping."),f("🔀","Mix it up","Switching between two or three spots, instead of one, often helps things stick."),f("⏰","Spacing","Meeting the same material again after a gap is a strong way to remember it."),f("🧃","Try this today","Practise in short rounds, with a one-minute break between each.")]},{id:"listen",title:"Listen to great playing",sub:"Fill your inner ear",hue:270,slides:[f("🎧","Hear the goal","When you listen to a good recording, you learn what you are aiming for."),f("🧭","Notice choices","Listen for how the player shapes the phrases, and where they breathe."),f("🗣️","Copy, then choose","Try imitating what you like, and then find your own way."),f("📻","Try this today","Listen to your piece twice before your next practice, and mark one thing you liked.")]},{id:"nerves",title:"Playing for other people",sub:"Handling nerves",hue:15,slides:[f("💓","Nerves are normal","A fast heartbeat before you play is common, even for professionals."),f("🎭","Practise performing","Play your piece for a friend, a pet, or a phone camera, so being watched feels familiar."),f("🐢","Slow breath","Breathe out slowly before you start. It helps your body settle."),f("🌟","Try this today","Play your piece once, all the way through, without stopping. Do it as a small performance.")]},{id:"counting",title:"Counting makes rhythm clear",sub:"Feel the beat",hue:200,slides:[f("🔢","Say the numbers","Counting out loud, one, two, three, four, shows you exactly where each note belongs."),f("🥁","Tap first","Tap the rhythm on your knee before you play it, without worrying about the notes."),f("➗","Subdivide","In the hard places, count the small beats, one and two and, to stay precise."),f("🎵","Try this today","Pick a tricky rhythm. Tap it and count it three times, and then play it.")]},{id:"dynamics",title:"Make it sound like music",sub:"Loud, soft and shape",hue:45,slides:[f("🔈","More than notes","Playing the right notes is the start. Loud and soft is what makes it music."),f("🌊","Shape phrases","Let a phrase rise and fall, like a sentence you are speaking."),f("🤫","Use the quiet","Soft playing needs control, so it is a skill worth practising on purpose."),f("🎨","Try this today","Play the same four bars twice. First very softly, and then with a big crescendo. Which do you prefer?")]}],de=[{id:"posture",title:"坐对位置，双手才放松",sub:"姿势与自由",hue:190,slides:[f("🪑","找到合适的高度","坐下时让前臂大致与琴键齐平，手肘稍微在身体前方。"),f("🦶","双脚踩稳","让双脚平放在地上，这样背和肩膀就不用撑住整个身体。"),f("🫁","慢慢呼气","检查肩膀。如果耸到耳朵附近，就呼一口气，让它们放下来。"),f("🎯","今天试试","弹琴之前，先慢慢呼吸三次，再把双手抖松十秒钟。")]},{id:"relax",title:"为什么紧张会让你变慢",sub:"放松的手更灵活",hue:140,slides:[f("✊","紧绷会累","手如果一直用力抓着琴键，就会消耗更多力气，很快就累了。"),f("🪶","用重量，不用蛮力","让手臂的重量沉进每个琴键，而不是靠肌肉往下压。"),f("🔍","找出紧的地方","手腕、拇指和肩膀常常在你没发觉时就绷紧了。"),f("🎼","今天试试","慢慢弹一个音阶，每个音都停一下，问问自己：现在哪里在用力？")]},{id:"slow",title:"慢弹的力量",sub:"速度是慢慢练出来的",hue:30,slides:[f("🐢","先慢","弹得慢，大脑才有时间有意识地选择每根手指和每个音。"),f("🧱","打好基础","认真的慢速重复会铺出一条干净的路，速度可以在上面慢慢增加。"),f("📈","一点一点加速","连续三次都弹得干净，再把速度提高一点点。"),f("✅","今天试试","挑一个难的小节，用一半的速度弹，直到觉得轻松为止。")]},{id:"metronome",title:"和节拍器交朋友",sub:"稳定的脉搏",hue:250,slides:[f("⏱️","稳定的朋友","节拍器不是裁判，它只是把拍子保持稳定，让你察觉自己的节奏。"),f("🐌","从慢开始","把速度调得够慢，即使遇到难的地方也不会抢拍。"),f("👂","听点与点之间","尽量让音符落在滴答声上，让耳朵记住什么叫稳定。"),f("🔧","今天试试","用节拍器练一段，再不用节拍器弹一遍，比较一下。")]},{id:"reading",title:"不慌张地读谱",sub:"视奏技巧",hue:60,slides:[f("👀","往前看","好的读谱者眼睛总比手早一拍，就像读书一样。"),f("🔁","继续往前","不要为了改错而停下来，让拍子继续走，这才是真正的读谱。"),f("🧩","看出规律","留意级进、跳进、重复音和和弦，而不是一个个念出音名。"),f("📖","今天试试","每天读一首简单的新曲。练读谱，简单又新鲜比困难又熟悉更有效。")]},{id:"ear",title:"训练你的耳朵",sub:"先听见，再弹出",hue:300,slides:[f("👂","耳朵带路","耳朵是音乐家最重要的工具，而且可以像肌肉一样训练。"),f("🎤","先唱出来","弹之前先哼唱下一句，手指会跟着耳朵的期待走。"),f("↕️","上行还是下行","从最简单的问题开始：这个音是往上还是往下？"),f("🎶","今天试试","挑一首你熟悉的歌，试着用耳朵找出它的前五个音。")]},{id:"scales",title:"音阶为什么值得练",sub:"琴键的地图",hue:100,slides:[f("🗺️","琴键的地图","大多数音乐都由音阶构成，练音阶就是在认识这张地图。"),f("✋","指法习惯","音阶会教会手掌一再出现在乐曲里的指法模式。"),f("🎚️","均匀的声音","试着让每个音一样大声、一样长。这是一个清楚又简单的目标。"),f("⏳","今天试试","在练曲子之前，先花两分钟慢而均匀地弹一个音阶。")]},{id:"hands",title:"先分手，再合手",sub:"分开，再合起来",hue:340,slides:[f("🙌","先分开","难的段落，先单手练会更容易。"),f("🔬","弄懂每一部分","左手练到不用思考，再换右手。"),f("🤝","慢慢合手","用很慢的速度把双手合起来。一开始觉得笨拙是很正常的。"),f("🧠","今天试试","取四个小节，先左手，再右手，然后慢速双手。明天再重复一次。")]},{id:"mistakes",title:"错音是一种信息",sub:"从错误中学习",hue:0,slides:[f("❌","不是失败","弹错一个音，其实是在告诉你该往哪里练。"),f("🔎","找出原因","是指法、节奏，还是读谱的问题？要改的是原因，不只是那个音。"),f("♻️","改正再重复","改好以后，把那个地方正确地弹几遍，让正确的方式变成习惯。"),f("😊","今天试试","弹错时，大声说出是哪里出了问题，然后冷静地再试一次。")]},{id:"sleep",title:"睡眠帮你记住",sub:"练习与休息",hue:230,slides:[f("🌙","大脑还在工作","研究认为，睡眠有助于大脑整理并巩固你当天学到的内容。"),f("📆","少量而常练","这也是为什么每天短时间练习，比临时抱佛脚更有效。"),f("🌅","早上检查","有时隔天一早，一个段落就变得容易了，尽管你什么也没多做。"),f("🛏️","今天试试","晚上练你最难的地方，明早再弹一次，看看有什么不同。")]},{id:"breaks",title:"休息一下再回来",sub:"间隔练习",hue:120,slides:[f("⏸️","有意地休息","短暂的休息能让你保持专注，一直硬撑只会让注意力下降。"),f("🔀","换着练","在两三个地方之间轮流练，通常比只练一个地方更容易记住。"),f("⏰","间隔","隔一段时间再接触同样的内容，是很有效的记忆方式。"),f("🧃","今天试试","分成几个短回合练习，每回合之间休息一分钟。")]},{id:"listen",title:"多听好的演奏",sub:"充实你的内在听觉",hue:270,slides:[f("🎧","听见目标","听一段好的录音，你就知道自己要追求的声音是什么样。"),f("🧭","留意选择","听演奏者怎么塑造乐句，又在哪里换气。"),f("🗣️","先模仿，再选择","试着模仿你喜欢的处理，然后再找出属于自己的方式。"),f("📻","今天试试","下次练习前，把你的曲子听两遍，并记下一个你喜欢的地方。")]},{id:"nerves",title:"为别人演奏",sub:"面对紧张",hue:15,slides:[f("💓","紧张很正常","上台前心跳加快很常见，连专业演奏家也一样。"),f("🎭","练习表演","把曲子弹给朋友、宠物或手机镜头听，让被注视变成熟悉的事。"),f("🐢","慢慢呼气","开始前慢慢吐气，有助于身体平静下来。"),f("🌟","今天试试","把曲子从头到尾弹一遍，中间不停下来，把它当成一场小小的演出。")]},{id:"counting",title:"数拍让节奏清楚",sub:"感受拍子",hue:200,slides:[f("🔢","把数字说出来","大声数一、二、三、四，能清楚看出每个音该落在哪里。"),f("🥁","先拍再弹","弹之前先用手在膝盖上拍出节奏，先不用管音符。"),f("➗","细分拍子","在难的地方数更小的拍子，一 和 二 和，让节奏保持精准。"),f("🎵","今天试试","挑一个难的节奏，拍三遍、数三遍，然后再弹出来。")]},{id:"dynamics",title:"让它听起来像音乐",sub:"强弱与塑形",hue:45,slides:[f("🔈","不只是音符","弹对音符只是开始，强弱变化才让它成为音乐。"),f("🌊","塑造乐句","让一个乐句有起有落，就像你在说一句话。"),f("🤫","善用轻声","轻柔的演奏需要控制力，值得有意识地去练。"),f("🎨","今天试试","把同样的四个小节弹两遍：第一遍非常轻，第二遍加上大的渐强。你更喜欢哪一种？")]}],pe={posture:["rings","timer","wave","keys"],relax:["wave","bridge","orbit","keys"],slow:["timer","grid","ecg","keys"],metronome:["ecg","timer","wave","staff"],reading:["staff","rings","grid","keys"],ear:["wave","orbit","ecg","staff"],scales:["grid","keys","wave","timer"],hands:["bridge","keys","orbit","neurons"],mistakes:["rings","orbit","ecg","neurons"],sleep:["wave","grid","rings","timer"],breaks:["timer","orbit","grid","rings"],listen:["wave","orbit","staff","keys"],nerves:["ecg","staff","wave","rings"],counting:["grid","ecg","timer","keys"],dynamics:["wave","staff","rings","orbit"]},Z={en:[{id:"focus",title:"Why piano players focus so well",sub:"Attention, trained",hue:210,slides:[{ic:"🎹",h:"Piano trains focus",b:"Playing the piano makes your brain do many things at once. That is a workout for attention."},{ic:"👀",h:"Eyes, ears, hands",b:"You read, listen and move your fingers in the same moment, so your brain must stay on task."},{ic:"🔁",h:"Small repeats",b:"Slow down, fix a mistake, try again. Each repeat practises paying attention on purpose."},{ic:"⏱️",h:"Try this today",b:"Ten focused minutes beat one distracted hour. Phone away, one short passage, play it slowly."}]},{id:"synapse",title:"How practice connects your neurons",sub:"Repetition rewires the brain",hue:280,slides:[{ic:"⚡",h:"Neurons talk",b:"Your brain is a network of neurons passing tiny signals across connections called synapses."},{ic:"🔁",h:"Practice strengthens",b:"When you repeat a movement, the same neurons fire together again and again, and those connections get stronger."},{ic:"🌉",h:"Both sides work together",b:"Playing with two hands makes both halves of your brain cooperate."},{ic:"🌱",h:"Be patient",b:"You do not need talent first. Slow, careful repetition is how the connections grow."}]},{id:"regions",title:"Which brain areas work when you play",sub:"A whole-brain activity",hue:160,slides:[{ic:"🎼",h:"The whole brain plays",b:"One simple melody wakes up many parts of your brain at once."},{ic:"✋",h:"Motor cortex",b:"It plans and controls your fingers, hands and arms."},{ic:"👂",h:"Auditory cortex",b:"It listens to what you play, so you can hear if the note was right."},{ic:"👁️",h:"Visual areas",b:"They read the notes on the page and follow the keys."},{ic:"⏳",h:"Timing and planning",b:"The cerebellum keeps time and smooths movement, while the front of the brain plans ahead."}]},{id:"session",title:"A practice session that works",sub:"Review, fix, then play",hue:20,slides:[{ic:"🗓️",h:"Short and daily",b:"Fifteen minutes every day beats two hours once a week, because the brain keeps what it meets again and again."},{ic:"🔁",h:"Three minutes of review",b:"Start with something you already know. Meeting it again is what makes it stay."},{ic:"🐢",h:"Four minutes to fix",b:"Take the spot where you get stuck. Play it slowly, in small pieces, and speed up only when it is clean."},{ic:"🎶",h:"End with a song you love",b:"Finish with something you enjoy. Ending on a success makes you want to come back tomorrow."}]},{id:"motivation",title:"Keeping the motivation to practise",sub:"Choice, progress, company",hue:330,slides:[{ic:"💪",h:"Three needs",b:"We keep going when we can choose, feel ourselves improving, and feel we are not alone."},{ic:"🧭",h:"Choose your path",b:"Pick the song and the speed. When the choice is yours, practice is your own project."},{ic:"📈",h:"See your progress",b:"Notice a passage that was hard last week and is smooth today. Real evidence beats empty praise."},{ic:"🤝",h:"Play for someone",b:"Share what you play with family or friends. It is also the best practice for nerves."}]}],zh:[{id:"focus",title:"为什么弹钢琴的孩子更专注",sub:"把注意力练出来",hue:210,slides:[{ic:"🎹",h:"钢琴练专注",b:"弹钢琴时大脑要同时做很多件事，这是对注意力的一次锻炼。"},{ic:"👀",h:"眼、耳、手",b:"看谱、听声音、动手指同时发生，大脑必须一直守在任务上。"},{ic:"🔁",h:"小小的重复",b:"放慢、纠错、再试一遍，每次重复都在练习有意识地集中注意力。"},{ic:"⏱️",h:"今天就试试",b:"专注十分钟，胜过分心一小时。放下手机，选一小段，慢慢弹。"}]},{id:"synapse",title:"练琴如何连接神经元",sub:"重复会重塑大脑",hue:280,slides:[{ic:"⚡",h:"神经元交流",b:"大脑是神经元组成的网络，通过叫做突触的连接传递微小的信号。"},{ic:"🔁",h:"练习让连接更强",b:"重复一个动作时，同一组神经元一次次一起放电，这些连接就会变得更牢固。"},{ic:"🌉",h:"左右脑一起合作",b:"双手弹琴会让左右两半大脑一起工作。"},{ic:"🌱",h:"请耐心",b:"不需要先有天赋。缓慢而认真的重复，就是连接生长的方式。"}]},{id:"regions",title:"弹琴时哪些脑区在工作",sub:"整个大脑的运动",hue:160,slides:[{ic:"🎼",h:"整个大脑在弹琴",b:"一段简单的旋律，就能同时唤醒大脑的许多区域。"},{ic:"✋",h:"运动皮层",b:"它负责规划和控制手指、手和手臂。"},{ic:"👂",h:"听觉皮层",b:"它倾听你弹出的声音，让你知道这个音对不对。"},{ic:"👁️",h:"视觉区域",b:"它们读取谱面上的音符，并跟随琴键。"},{ic:"⏳",h:"节奏与规划",b:"小脑负责节奏和动作的流畅，大脑前部负责提前规划。"}]},{id:"session",title:"真正有效的一次练琴",sub:"先复习，再攻克，最后弹喜欢的曲子",hue:20,slides:[{ic:"🗓️",h:"短而天天练",b:"每天练十五分钟，胜过一周只练一次两小时，因为大脑会记住反复遇到的东西。"},{ic:"🔁",h:"先复习三分钟",b:"从已经会的内容开始，再次接触才能让它留下来。"},{ic:"🐢",h:"再用四分钟攻克",b:"选一个卡住的地方，放慢速度分成小段，弹干净了再提速。"},{ic:"🎶",h:"以喜欢的曲子收尾",b:"最后弹一首喜欢的曲子，以成功结束，明天你还会想再来。"}]},{id:"motivation",title:"保持练琴的动力",sub:"选择、进步、陪伴",hue:330,slides:[{ic:"💪",h:"三种需要",b:"当我们能自己选择、感到自己在进步、并且不孤单时，就更愿意坚持。"},{ic:"🧭",h:"自己选路线",b:"自己挑曲子、定速度，选择权在你手里，练琴就是你自己的小项目。"},{ic:"📈",h:"看见进步",b:"留意上周很难、今天已经流畅的乐句，真实的证据胜过空洞的夸奖。"},{ic:"🤝",h:"弹给别人听",b:"把你弹的曲子分享给家人朋友，这也是克服紧张的最好练习。"}]}]};function H(t){if(t)try{const a=t.currentTime,s=t.createBufferSource(),v=Math.floor(t.sampleRate*.35),e=t.createBuffer(1,v,t.sampleRate),S=e.getChannelData(0);for(let m=0;m<v;m++)S[m]=(Math.random()*2-1)*(1-m/v);s.buffer=e;const i=t.createBiquadFilter();i.type="bandpass",i.frequency.setValueAtTime(500,a),i.frequency.exponentialRampToValueAtTime(5e3,a+.3),i.Q.value=1.2;const o=t.createGain();o.gain.setValueAtTime(1e-4,a),o.gain.exponentialRampToValueAtTime(.18,a+.08),o.gain.exponentialRampToValueAtTime(1e-4,a+.35),s.connect(i),i.connect(o),o.connect(t.destination),s.start(a);const h=t.createOscillator(),d=t.createGain();h.type="sine",h.frequency.value=1318.5,d.gain.setValueAtTime(1e-4,a+.2),d.gain.exponentialRampToValueAtTime(.1,a+.23),d.gain.exponentialRampToValueAtTime(1e-4,a+1.1),h.connect(d),d.connect(t.destination),h.start(a+.2),h.stop(a+1.2)}catch{}}function ye(t,a,s,v,e){const S=e/1e3;let i=11;const o=()=>(i=i*16807%2147483647)/2147483647;for(let p=0;p<70;p++){const c=o()*a,g=o()*s*.5,w=.45+.55*Math.abs(Math.sin(S*(.6+o())+p));t.fillStyle=`rgba(255,255,255,${.12+.5*w*o()})`,t.fillRect(c,g,1.4,1.4)}const h=a*.78,d=s*.17,m=a*.07,M=t.createRadialGradient(h,d,m*.6,h,d,m*4);M.addColorStop(0,`hsla(${v+190} 90% 80% / .35)`),M.addColorStop(1,"transparent"),t.fillStyle=M,t.fillRect(h-m*4,d-m*4,m*8,m*8);const T=t.createRadialGradient(h-m*.3,d-m*.3,m*.1,h,d,m);T.addColorStop(0,"#fffbe8"),T.addColorStop(1,`hsl(${v+200} 40% 70%)`),t.fillStyle=T,t.beginPath(),t.arc(h,d,m,0,7),t.fill(),t.fillStyle="rgba(120,130,160,.22)",t.beginPath(),t.arc(h-m*.25,d+m*.1,m*.22,0,7),t.fill(),t.beginPath(),t.arc(h+m*.3,d-m*.25,m*.15,0,7),t.fill()}f